/**
 * 🌳 SYSTEM: IRMINSUL DATABASE CLEANER
 * ==========================================================
 * @file clean-db.js
 * @path backend/clean-db.js
 * @description Automatically scans the current database for duplicate unique indexes 
 * generated by Sequelize's sync({alter:true}) bug, and drops them.
 * This preserves all existing user data.
 * ==========================================================
 */

import { sequelize } from "./config/database.js";

async function cleanDuplicateIndexes() {
  try {
    // 1. Kiểm tra kết nối
    await sequelize.authenticate();
    console.log("🔌 Kết nối MySQL thành công! Đang quét cấu trúc index...");

    // 2. Lấy tên database hiện tại
    const [dbResult] = await sequelize.query("SELECT DATABASE() as db");
    const dbName = dbResult[0]?.db;
    if (!dbName) {
      throw new Error("Không thể xác định tên database đang kết nối.");
    }
    console.log(`📂 Database hiện tại: ${dbName}`);

    // 3. Lấy toàn bộ danh sách index trong database
    const [indexes] = await sequelize.query(`
      SELECT TABLE_NAME, INDEX_NAME 
      FROM INFORMATION_SCHEMA.STATISTICS 
      WHERE TABLE_SCHEMA = :dbName
    `, {
      replacements: { dbName }
    });

    const dropQueries = [];

    // 4. Nhận diện các index trùng lặp theo quy luật đặt tên hậu tố số của MySQL
    for (const idx of indexes) {
      const tableName = idx.TABLE_NAME;
      const indexName = idx.INDEX_NAME;

      let shouldDrop = false;

      // Tìm các index có hậu tố _1, _2, _3... trùng lặp
      if (tableName === "users" && /^username_\d+$/.test(indexName)) {
        shouldDrop = true;
      } else if (tableName === "achievements" && /^code_\d+$/.test(indexName)) {
        shouldDrop = true;
      } else if (tableName === "areas" && /^name_\d+$/.test(indexName)) {
        shouldDrop = true;
      } else if (tableName === "reputations" && /^rank_\d+$/.test(indexName)) {
        shouldDrop = true;
      } else if (tableName === "commentlikes" && indexName === "commentlikes_user_id_comment_id") {
        shouldDrop = true;
      }

      if (shouldDrop) {
        dropQueries.push({ tableName, indexName });
      }
    }

    if (dropQueries.length === 0) {
      console.log("✅ Tuyệt vời! Không phát hiện index trùng lặp nào cần dọn dẹp.");
      return;
    }

    console.log(`🔍 Phát hiện ${dropQueries.length} index trùng lặp rác. Tiến hành dọn dẹp...`);

    // 5. Chạy các câu lệnh ALTER TABLE để xóa index trùng lặp
    for (const q of dropQueries) {
      console.log(`🗑️  Đang xóa index [${q.indexName}] trên bảng [${q.tableName}]...`);
      try {
        await sequelize.query(`ALTER TABLE \`${q.tableName}\` DROP INDEX \`${q.indexName}\``);
      } catch (err) {
        console.error(`❌ Lỗi khi xóa index ${q.indexName}:`, err.message);
      }
    }

    console.log("🎉 Hoàn tất dọn dẹp database thành công! Toàn bộ index rác đã được giải phóng.");
  } catch (error) {
    console.error("❌ Đã xảy ra lỗi khi dọn dẹp:", error);
  } finally {
    // Đóng kết nối
    await sequelize.close();
    console.log("🔌 Đã ngắt kết nối database.");
  }
}

cleanDuplicateIndexes();
